import sys

def main():
    import sys
    import collections

    input = sys.stdin.read().split()
    n = int(input[0])
    words = input[1:]

    def calculate_length_with_abbreviation(words, start1, end1, start2, end2):
        abbreviated_segment = ''.join(w[0].upper() for w in words[start1:end1+1])
        new_words = words[:start1] + [abbreviated_segment] + words[end1+1:start2] + [abbreviated_segment] + words[end2+1:]
        return len(' '.join(new_words))

    min_length = len(' '.join(words))
    segment_map = collections.defaultdict(list)

    for i in range(n):
        for j in range(i, n):
            segment = ' '.join(words[i:j+1])
            segment_map[segment].append((i, j))

    for segment, positions in segment_map.items():
        if len(positions) > 1:
            for k in range(len(positions)):
                for l in range(k+1, len(positions)):
                    start1, end1 = positions[k]
                    start2, end2 = positions[l]
                    if end1 < start2:
                        new_length = calculate_length_with_abbreviation(words, start1, end1, start2-len(segment.split())+1, end2-len(segment.split())+1)
                        min_length = min(min_length, new_length)

    print(min_length)

main()
